import { ResourceAllocationData } from '../types';
import { hasPublicisChartEntry } from './hasPublicisChartEntry';

const extractRankingChartData = (
  data?: ResourceAllocationData,
): ResourceAllocationData | undefined => {
  if (!data || typeof data !== 'object') {
    return undefined;
  }

  if (data.datasets) {
    return data;
  }

  const nestedEntry = Object.values(data)[0] as
    ResourceAllocationData | undefined;
  return nestedEntry && typeof nestedEntry === 'object'
    ? nestedEntry
    : undefined;
};

const hasRankingDatasets = (chart: ResourceAllocationData): boolean =>
  Array.isArray(chart.datasets) &&
  chart.datasets.some(
    (dataset) => Array.isArray(dataset.data) && dataset.data.length > 0,
  );

export const hasRankingChartData = (data?: ResourceAllocationData): boolean => {
  const chartData = extractRankingChartData(data);

  if (!chartData || chartData.empty) {
    return false;
  }

  return (
    hasRankingDatasets(chartData) ||
    hasPublicisChartEntry(chartData.overview_graph as ResourceAllocationData)
  );
};
